const combustion = (
  name: string,
  power: string,
  displacement: string,
  maxTorque = unpublished,
  torqueRpm = unpublished,
  note?: string,
  classification?: Pick<ModelVersion, 'type' | 'powertrainGroup'>,
): ModelVersion => ({
  name,
  type: classification?.type ?? 'Gasolina',
  ...classification,
  power,
  displacement,
  maxTorque,
  torqueScope: 'Motor de combustión',
  torqueRpm,
  note,
});

const electric = (
  name: string,
  power: string,
  battery: string,
  maxTorque = unpublished,
  note?: string,
): ModelVersion => ({
  name,
  type: /pila de combustible|hidrógeno/i.test(name) ? 'Hidrógeno · pila de combustible' : 'Eléctrico',
  power,
  displacement: 'No aplica: propulsión eléctrica',
  maxTorque,
  torqueScope: 'Motor eléctrico o sistema, según dato publicado',
  torqueRpm: 'No comparable a un motor térmico; el régimen no se publica',
  note: battery + (note ? ` ${note}` : ''),
});

const hybrid = (
  name: string,
  power: string,
  displacement: string,
  note: string,
  maxTorque = unpublished,
  torqueRpm = unpublished,
): ModelVersion => ({
  name,
  type: /PHEV|enchufable/i.test(name) ? 'Híbrido enchufable · PHEV gasolina' : 'Híbrido no enchufable · HEV gasolina',
  power,
  displacement,
  maxTorque,
  torqueScope: 'Sistema híbrido; no confundir con el par aislado del motor térmico',
  torqueRpm,
  note,
});

